########## overrides/app/components/pdpProductInfo/index.tsx
     1	import React from 'react';
     2	import DOMPurify from 'isomorphic-dompurify';
     3	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     4	import { SPACE_DESCRIPTION_TO_META, SPACE_MODEL_INFO_TO_STYLE_CODE } from 'app/theme/components/pdpProductInfo';
     5	
     6	type PdpProductInfoProps = {
     7	  name: string;
     8	  price: string;
     9	  description?: string;
    10	  modelInfo?: string;
    11	  styleCode?: string;
    12	};
    13	
    14	// ---------------------------------------------------------------------------
    15	// All styling lives in theme/components/pdpProductInfo.ts and is consumed via
    16	// useMultiStyleConfig('ZimmPdpProductInfo') → __css. The only exceptions are the
    17	// two conditional bottom margins, which depend on which optional props were
    18	// supplied and so cannot be expressed in baseStyle; their values are imported
    19	// from the theme file rather than written here.
    20	// ---------------------------------------------------------------------------
    21	
    22	/**
    23	 * Renders static product information for the PDP: name, price, description,
    24	 * and optional model copy / style code.
    25	 */
    26	const PdpProductInfo = ({ name, price, description, modelInfo, styleCode }: PdpProductInfoProps) => {
    27	  const styles = useMultiStyleConfig('ZimmPdpProductInfo', {});
    28	  const hasMeta = Boolean(modelInfo || styleCode);
    29	
    30	  return (
    31	    <chakra.div>
    32	      <chakra.h1 __css={styles.name}>{name}</chakra.h1>
    33	
    34	      <chakra.p data-testid="product-price" __css={styles.price}>
    35	        {price}
    36	      </chakra.p>
    37	
    38	      {description && (
    39	        <chakra.div
    40	          data-testid="product-description"
    41	          __css={styles.description}
    42	          marginBottom={hasMeta ? SPACE_DESCRIPTION_TO_META : 0}
    43	          dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(description) }}
    44	        />
    45	      )}
    46	
    47	      {hasMeta && (
    48	        <chakra.div>
    49	          {modelInfo && (
    50	            <chakra.div
    51	              data-testid="product-model-info"
    52	              __css={styles.modelInfo}
    53	              marginBottom={styleCode ? SPACE_MODEL_INFO_TO_STYLE_CODE : 0}
    54	              dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(modelInfo) }}
    55	            />
    56	          )}
    57	          {styleCode && (
    58	            <chakra.p data-testid="product-style-code" __css={styles.styleCode}>
    59	              Style Code: {styleCode}
    60	            </chakra.p>
    61	          )}
    62	        </chakra.div>
    63	      )}
    64	    </chakra.div>
    65	  );
    66	};
    67	
    68	export { PdpProductInfo };
    69	export default PdpProductInfo;
########## overrides/app/components/breadcrumb/index.tsx
     1	import React from 'react';
     2	import { Link as RouteLink } from 'react-router-dom';
     3	import { Box, Text } from '@chakra-ui/react';
     4	
     5	type BreadcrumbCategory = {
     6	  id: string;
     7	  name: string;
     8	};
     9	
    10	const categoryUrlBuilder = (category: BreadcrumbCategory) =>
    11	  encodeURI(`/category/${category.id}`);
    12	
    13	type BreadcrumbProps = {
    14	  categories: readonly BreadcrumbCategory[];
    15	  /**
    16	   * Non-link terminal crumb — typically the product name.
    17	   * Breaks to a new line on mobile; stays inline on desktop.
    18	   */
    19	  currentPage?: string;
    20	};
    21	
    22	const BASE_STYLE = {
    23	  textStyle: 'caption',
    24	  textTransform: 'uppercase' as const,
    25	  color: 'text.default',
    26	};
    27	
    28	const LINK_PROPS = {
    29	  ...BASE_STYLE,
    30	  textDecoration: 'none',
    31	  _hover: { opacity: 0.6 },
    32	  sx: {
    33	    transition: 'opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
    34	  },
    35	};
    36	
    37	const Separator = () => (
    38	  <Text as="span" aria-hidden="true" {...BASE_STYLE} mx="2xs">
    39	    /
    40	  </Text>
    41	);
    42	
    43	/**
    44	 * PDP breadcrumb reflecting the product's category path.
    45	 * HOME is always the first crumb; currentPage is the non-link terminal item.
    46	 */
    47	const Breadcrumb = ({ categories, currentPage }: BreadcrumbProps) => {
    48	  const hasMoreAfterHome = categories.length > 0 || Boolean(currentPage);
    49	
    50	  return (
    51	    <Box as="nav" aria-label="Breadcrumb">
    52	      <Box as="ol" listStyleType="none" m={0} p={0} sx={{ paddingInlineStart: 0 }}>
    53	        <Box as="li" display="inline">
    54	          <Text as={RouteLink} to="/" {...LINK_PROPS}>
    55	            Home
    56	          </Text>
    57	          {hasMoreAfterHome && <Separator />}
    58	        </Box>
    59	
    60	        {categories.map((category, index) => {
    61	          const isLastCrumb = index === categories.length - 1 && !currentPage;
    62	          return (
    63	            <Box as="li" key={category.id} display="inline">
    64	              <Text as={RouteLink} to={categoryUrlBuilder(category)} {...LINK_PROPS}>
    65	                {category.name}
    66	              </Text>
    67	              {!isLastCrumb && <Separator />}
    68	            </Box>
    69	          );
    70	        })}
    71	
    72	        {currentPage && (
    73	          <Box as="li" display={{ base: 'block', md: 'inline' }}>
    74	            <Text as="span" aria-current="page" {...BASE_STYLE}>
    75	              {currentPage}
    76	            </Text>
    77	          </Box>
    78	        )}
    79	      </Box>
    80	    </Box>
    81	  );
    82	};
    83	
    84	export type { BreadcrumbCategory };
    85	export { Breadcrumb };
    86	export default Breadcrumb;

